SELECT id, email, salary, hire_date, is_remote, level, LEAD(salary) OVER w_ordered AS next_salary, LAG(salary) OVER w_ordered AS prev_salary, ROW_NUMBER() OVER w_ordered AS seq_no, ROW_NUMBER() OVER w_hist AS event_seq FROM employees WHERE MONTH(hire_date) IN (5, 6, 12) WINDOW w_ordered AS (PARTITION BY dept_id ORDER BY salary, id), w_hist AS (PARTITION BY manager_id ORDER BY hire_date DESC, id);
